// docs/contract.json and the official LogEvent schema (uuid, published,
// eventType, severity, displayMessage, nested actor/outcome).

namespace OktaSyslog;

public sealed record LogEvent(
    string Uuid,
    string Published,
    string EventType,
    string Severity,
    string? DisplayMessage,
    string ActorAlternateId,
    string OutcomeResult);

