[tool_call Write] {"file_path":"SystemLogClient.cs","content":"// HTTP client for GET /api/v1/logs per the Okta System Log reference:
// SSWS token auth, Link rel="next" pagination with opaque after cursors,
// X-Rate-Limit-{Limit,Remaining,Reset} on every response (reset is UTC epoch
// seconds). All rate arithmetic is anchored on the response's own Date header
// so the machine clock never participates; all waiting goes through the
// injected wait delegate.

using System.Text.Json;
using System.Text.RegularExpressions;

namespace OktaSyslog;

public sealed class SystemLogClient
{
    private const int MaxAttempts = 3;

    private static readonly Regex NextLinkPattern =
        new("<(?<url>[^>]*)>\\s*;\\s*rel=\"next\"", RegexOptions.Compiled);

    private readonly Uri _orgBase;
    private readonly string _apiToken;
    private readonly HttpClient _http;
    private readonly Func<TimeSpan, Task> _wait;

    // Wait owed before the next request may leave, computed from the response
    // that spent the budget (429 or Remaining=0). Survives across
    // FetchPageAsync calls, including after the terminal 429 throw, so a later
    // request is still gated until the documented reset moment.
    private TimeSpan? _pendingGate;

    public RateLimitInfo? LastRateLimit { get; private set; }

    public SystemLogClient(string orgBaseUrl, string apiToken, HttpClient http, Func<TimeSpan, Task> wait)
    {
        _orgBase = new Uri(orgBaseUrl, UriKind.Absolute);
        _apiToken = apiToken;
        _http = http;
        _wait = wait;
    }

    public async Task<LogPage> FetchPageAsync(string url)
    {
        Uri requestUri =
            Uri.TryCreate(url, UriKind.Absolute, out Uri? absolute)
            && (absolute.Scheme == Uri.UriSchemeHttp || absolute.Scheme == Uri.UriSchemeHttps)
                ? absolute
                : new Uri(_orgBase, url);

        for (int attempt = 1; ; attempt++)
        {
            if (_pendingGate is TimeSpan gate)
            {
                _pendingGate = null;
                await _wait(gate);
            }

            using var request = new HttpRequestMessage(HttpMethod.Get, requestUri);
            request.Headers.TryAddWithoutValidation("Accept", "application/json");
            // Okta next links stay on the org origin; never leak the token to
            // any other host a URL might point at.
            if (IsOrgOrigin(requestUri))
                request.Headers.TryAddWithoutValidation("Authorization", "SSWS " + _apiToken);

            using HttpResponseMessage response = await _http.SendAsync(request);
            RateLimitInfo? rate = ParseRateHeaders(response);
            if (rate is not null)
                LastRateLimit = rate;

            if ((int)response.StatusCode == 429)
            {
                _pendingGate = GateUntilReset(response, rate);
                if (attempt >= MaxAttempts)
                {
                    string errorCode = await ExtractErrorCodeAsync(response);
                    throw new OktaRateLimitException(
                        $"Okta rate limit exceeded after {MaxAttempts} attempts (errorCode {errorCode}); " +
                        $"window resets at epoch second {rate?.ResetEpochSeconds ?? 0}.",
                        rate?.ResetEpochSeconds ?? 0);
                }
                continue;
            }

            // Budget spent without a 429: gate the next request until reset,
            // whatever this response's status turns out to be.
            if (rate is { Remaining: <= 0 })
                _pendingGate = GateUntilReset(response, rate);

            if (!response.IsSuccessStatusCode)
            {
                string errorCode = await ExtractErrorCodeAsync(response);
                throw new HttpRequestException(
                    $"Okta System Log request failed with status {(int)response.StatusCode} (errorCode {errorCode}).");
            }

            string json = await response.Content.ReadAsStringAsync();
            string? nextUrl = ParseNextLink(response);
            return new LogPage(ParseEvents(json), nextUrl, ExtractAfter(nextUrl));
        }
    }

    private bool IsOrgOrigin(Uri uri) =>
        uri.Scheme == _orgBase.Scheme
        && string.Equals(uri.Host, _orgBase.Host, StringComparison.OrdinalIgnoreCase)
        && uri.Port == _orgBase.Port;

    // Reset epoch minus the server's own Date header; a missing Date yields a
    // zero wait rather than falling back to the local clock.
    private static TimeSpan GateUntilReset(HttpResponseMessage response, RateLimitInfo? rate)
    {
        if (rate is null || response.Headers.Date is not DateTimeOffset serverNow)
            return TimeSpan.Zero;
        TimeSpan wait = DateTimeOffset.FromUnixTimeSeconds(rate.ResetEpochSeconds) - serverNow;
        return wait > TimeSpan.Zero ? wait : TimeSpan.Zero;
    }

    private static RateLimitInfo? ParseRateHeaders(HttpResponseMessage response)
    {
        return TryHeader(response, "X-Rate-Limit-Limit") is string l && int.TryParse(l, out int limit)
            && TryHeader(response, "X-Rate-Limit-Remaining") is string r && int.TryParse(r, out int remaining)
            && TryHeader(response, "X-Rate-Limit-Reset") is string s && long.TryParse(s, out long reset)
                ? new RateLimitInfo(limit, remaining, reset)
                : null;
    }

    private static string? TryHeader(HttpResponseMessage response, string name) =>
        response.Headers.TryGetValues(name, out IEnumerable<string>? values) ? values.FirstOrDefault() : null;

    private static string? ParseNextLink(HttpResponseMessage response)
    {
        if (!response.Headers.TryGetValues("Link", out IEnumerable<string>? values))
            return null;
        foreach (string value in values)
        {
            Match match = NextLinkPattern.Match(value);
            if (match.Success)
                return match.Groups["url"].Value;
        }
        return null;
    }

    // Surfaces the cursor for checkpointing only; requests always follow the
    // next link itself because the cursor is opaque and system generated.
    private static string? ExtractAfter(string? nextUrl)
    {
        if (nextUrl is null)
            return null;
        int q = nextUrl.IndexOf('?');
        if (q < 0)
            return null;
        foreach (string pair in nextUrl[(q + 1)..].Split('&', StringSplitOptions.RemoveEmptyEntries))
        {
            int eq = pair.IndexOf('=');
            if (Uri.UnescapeDataString(eq < 0 ? pair : pair[..eq]) == "after")
                return Uri.UnescapeDataString(eq < 0 ? "" : pair[(eq + 1)..]);
        }
        return null;
    }

    private static async Task<string> ExtractErrorCodeAsync(HttpResponseMessage response)
    {
        try
        {
            using var doc = JsonDocument.Parse(await response.Content.ReadAsStringAsync());
            if (doc.RootElement.ValueKind == JsonValueKind.Object
                && doc.RootElement.TryGetProperty("errorCode", out JsonElement code)
                && code.ValueKind == JsonValueKind.String)
                return code.GetString()!;
        }
        catch (JsonException)
        {
        }
        return "unknown";
    }

    private static IReadOnlyList<LogEvent> ParseEvents(string json)
    {
        using var doc = JsonDocument.Parse(json);
        var events = new List<LogEvent>();
        foreach (JsonElement el in doc.RootElement.EnumerateArray())
        {
            events.Add(new LogEvent(
                GetString(el, "uuid"),
                GetString(el, "published"),
                GetString(el, "eventType"),
                GetString(el, "severity"),
                GetNullableString(el, "displayMessage"),
                GetNested(el, "actor", "alternateId"),
                GetNested(el, "outcome", "result")));
        }
        return events;
    }

    private static string GetString(JsonElement el, string name) => GetNullableString(el, name) ?? "";

    private static string? GetNullableString(JsonElement el, string name) =>
        el.TryGetProperty(name, out JsonElement value) && value.ValueKind == JsonValueKind.String
            ? value.GetString()
            : null;

    private static string GetNested(JsonElement el, string objectName, string name) =>
        el.TryGetProperty(objectName, out JsonElement nested) && nested.ValueKind == JsonValueKind.Object
            ? GetString(nested, name)
            : "";
