using System.Text;

namespace OktaSyslog;

public sealed class SystemLogExporter
{
    private readonly SystemLogClient _client;
    private readonly Func<string?> _loadCursor;
    private readonly Action<string> _saveCursor;
    private readonly Func<IReadOnlyList<LogEvent>, Task> _deliver;
    private readonly ISet<string> _deliveredUuids;

    public SystemLogExporter(
        SystemLogClient client,
        Func<string?> loadCursor,
        Action<string> saveCursor,
        Func<IReadOnlyList<LogEvent>, Task> deliver)
        : this(client, loadCursor, saveCursor, deliver, new HashSet<string>(StringComparer.Ordinal))
    {
    }

    /// <summary>
    /// The `after` cursor alone cannot tell a resumed sweep which boundary
    /// events the previous run already shipped, so deployments that must stay
    /// exactly-once across process restarts persist the delivered-uuid set
    /// beside the cursor and pass it here. The four-argument overload keeps
    /// the set in memory, which covers every resume within this exporter's
    /// lifetime.
    /// </summary>
    public SystemLogExporter(
        SystemLogClient client,
        Func<string?> loadCursor,
        Action<string> saveCursor,
        Func<IReadOnlyList<LogEvent>, Task> deliver,
        ISet<string> deliveredUuids)
    {
        _client = client;
        _loadCursor = loadCursor;
        _saveCursor = saveCursor;
        _deliver = deliver;
        _deliveredUuids = deliveredUuids;
    }

    public async Task<SweepReport> RunSweepAsync(string since, string filter, int limit)
    {
        int pagesDelivered = 0, eventsDelivered = 0, duplicatesSkipped = 0;
        string url = BuildPollingQuery(since, filter, limit, _loadCursor());

        while (true)
        {
            LogPage page = await _client.FetchPageAsync(url);
            if (page.Events.Count == 0)
                break;

            var fresh = new List<LogEvent>();
            var inPage = new HashSet<string>(StringComparer.Ordinal);
            foreach (LogEvent ev in page.Events)
            {
                if (_deliveredUuids.Contains(ev.Uuid) || !inPage.Add(ev.Uuid))
                    duplicatesSkipped++;
                else
                    fresh.Add(ev);
            }

            // Deliver before checkpointing, even when dedupe leaves the batch
            // empty; uuids count as delivered only once the sink accepts them,
            // so a failed page stays eligible for redelivery on resume.
            await _deliver(fresh);
            foreach (LogEvent ev in fresh)
                _deliveredUuids.Add(ev.Uuid);
            pagesDelivered++;
            eventsDelivered += fresh.Count;

            if (page.NextAfter is not null)
                _saveCursor(page.NextAfter);
            if (page.NextUrl is null)
                break;
            url = page.NextUrl;
        }

        return new SweepReport(pagesDelivered, eventsDelivered, duplicatesSkipped);
    }

    private static string BuildPollingQuery(string since, string filter, int limit, string? after)
    {
        var sb = new StringBuilder("/api/v1/logs?since=")
            .Append(Uri.EscapeDataString(since))
            .Append("&filter=").Append(Uri.EscapeDataString(filter))
            .Append("&limit=").Append(limit)
            .Append("&sortOrder=ASCENDING");
        if (after is not null)
            sb.Append("&after=").Append(Uri.EscapeDataString(after));
        return sb.ToString();
    }
